-- Multi-tenant schema for Nyota Herbal & Natural Wellness. Run in Supabase SQL editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null unique,role text not null default 'customer' check(role in ('super_admin','admin','customer')),display_name text,business_name text,phone text,status text not null default 'active' check(status in ('active','suspended','pending')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null check(length(name) between 1 and 160),description text not null default '' check(length(description)<=5000),category text not null default 'Other',price numeric(12,2) check(price is null or price>=0),image_url text,active boolean not null default true,stock_quantity integer not null default 0 check(stock_quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists products_owner_created_idx on public.products(owner_id,created_at desc);
create table if not exists public.customer_inquiries(id uuid primary key default gen_random_uuid(),owner_id uuid references public.profiles(id) on delete set null,customer_name text not null check(length(customer_name) between 1 and 160),phone text not null check(length(phone) between 5 and 40),message text not null check(length(message) between 1 and 5000),status text not null default 'new' check(status in ('new','in_progress','resolved')),created_at timestamptz not null default now());
create index if not exists inquiries_owner_created_idx on public.customer_inquiries(owner_id,created_at desc);
create table if not exists public.audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id) on delete set null,actor_email text,actor_role text not null,action text not null,target_type text not null,target_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists audit_created_idx on public.audit_logs(created_at desc);
create or replace function public.current_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and status='active' $$;
create or replace function public.is_active_user() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and status='active') $$;
alter table public.profiles enable row level security; alter table public.products enable row level security; alter table public.customer_inquiries enable row level security; alter table public.audit_logs enable row level security;
drop policy if exists "profile self or super read" on public.profiles; create policy "profile self or super read" on public.profiles for select to authenticated using(id=auth.uid() or public.current_role()='super_admin');
drop policy if exists "self update limited profile fields" on public.profiles; create policy "self update limited profile fields" on public.profiles for update to authenticated using(id=auth.uid() and public.is_active_user()) with check(id=auth.uid() and role=public.current_role() and status='active');
drop policy if exists "super update profiles" on public.profiles; create policy "super update profiles" on public.profiles for update to authenticated using(public.current_role()='super_admin') with check(public.current_role()='super_admin');
drop policy if exists "public read active products" on public.products; create policy "public read active products" on public.products for select to anon,authenticated using(active=true or owner_id=auth.uid() or public.current_role()='super_admin');
drop policy if exists "admins insert own products" on public.products; create policy "admins insert own products" on public.products for insert to authenticated with check(owner_id=auth.uid() and public.current_role() in ('admin','super_admin') and public.is_active_user());
drop policy if exists "admins update own products super all" on public.products; create policy "admins update own products super all" on public.products for update to authenticated using((owner_id=auth.uid() and public.current_role() in ('admin','super_admin')) or public.current_role()='super_admin') with check((owner_id=auth.uid() and public.current_role() in ('admin','super_admin')) or public.current_role()='super_admin');
drop policy if exists "admins delete own products super all" on public.products; create policy "admins delete own products super all" on public.products for delete to authenticated using((owner_id=auth.uid() and public.current_role() in ('admin','super_admin')) or public.current_role()='super_admin');
drop policy if exists "public submit inquiries" on public.customer_inquiries; create policy "public submit inquiries" on public.customer_inquiries for insert to anon,authenticated with check(length(customer_name) between 1 and 160 and length(phone) between 5 and 40 and length(message) between 1 and 5000);
drop policy if exists "seller read own inquiries super all" on public.customer_inquiries; create policy "seller read own inquiries super all" on public.customer_inquiries for select to authenticated using((owner_id=auth.uid() and public.current_role() in ('admin','super_admin')) or public.current_role()='super_admin');
drop policy if exists "seller update own inquiries super all" on public.customer_inquiries; create policy "seller update own inquiries super all" on public.customer_inquiries for update to authenticated using((owner_id=auth.uid() and public.current_role() in ('admin','super_admin')) or public.current_role()='super_admin') with check((owner_id=auth.uid() and public.current_role() in ('admin','super_admin')) or public.current_role()='super_admin');
drop policy if exists "audit insert own events" on public.audit_logs; create policy "audit insert own events" on public.audit_logs for insert to authenticated with check(actor_id=auth.uid() and actor_role=public.current_role());
drop policy if exists "super admin reads all audit" on public.audit_logs; create policy "super admin reads all audit" on public.audit_logs for select to authenticated using(public.current_role()='super_admin');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
drop policy if exists "public read product images" on storage.objects; create policy "public read product images" on storage.objects for select using(bucket_id='product-images');
drop policy if exists "seller upload own image folder" on storage.objects; create policy "seller upload own image folder" on storage.objects for insert to authenticated with check(bucket_id='product-images' and (storage.foldername(name))[1]=auth.uid()::text and public.current_role() in ('admin','super_admin') and public.is_active_user());
drop policy if exists "seller update own image folder" on storage.objects; create policy "seller update own image folder" on storage.objects for update to authenticated using(bucket_id='product-images' and ((storage.foldername(name))[1]=auth.uid()::text or public.current_role()='super_admin')) with check(bucket_id='product-images' and ((storage.foldername(name))[1]=auth.uid()::text or public.current_role()='super_admin'));
drop policy if exists "seller delete own image folder" on storage.objects; create policy "seller delete own image folder" on storage.objects for delete to authenticated using(bucket_id='product-images' and ((storage.foldername(name))[1]=auth.uid()::text or public.current_role()='super_admin'));
-- Roles must be assigned through trusted server-side tooling only. Never allow self-promotion.
